#!/usr/bin/env python3
# reserve_L53c.py — 새 과 L53c(바닷속 버터 부교 ③ 동전 펌프와 짝 손님) · 세계 s53(c)
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
T = '[2026-11-13 새 과 L53c]'
new = {
 '큰 놋쇠 펌프 기계의 둥근 창 — 세로 유리 문짝 왼쪽 칸에 흰 소금 자루 셋 ↑ · 오른쪽 칸에 칼 둘 ↓': f'Na⁺-K⁺ 펌프의 셈과 걸음(1회에 Na⁺ 3 밖으로 · K⁺ 2 안으로 · ATP 직접) 전용 {T} — L53c s3 ~ s6. 【동전 투입구 크랭크 펌프】를 띠를 꿰뚫는 큰 기계로 키웠다: 밑면 투입구로 ↑ 오르는 동전(ATP — 세포 안에서) · 왼쪽 옆구리에 나무 손잡이 도장이 찍은 붉은 도장 자국(인산화 → 문짝이 돎 = 모양 변화 · Na⁺ 친화성 ↓) · 오른쪽 아래 놋쇠 면에서 들뜨고 기계 밑으로 떨어지는 붉은 조각(인산기 탈리 → 원래 모양 · K⁺ 를 안에 내림). 문짝 = L53b 의 회전문(운반단백질 — 틈이 아니다). 기계 밑에 다가선 자루 셋 = 세포질 Na⁺ 3 결합 · 기계 위의 칼 둘 = K⁺ 2 결합. ⚠ 자루 · 칼의 수(셋 · 둘)와 화살 방향은 PIL(L53c_pil1.py)로 그렸다 — Gemini 에게는 창을 「비워」 그리게 했다.',
 '버터 띠를 꿰뚫어 세로로 선 큰 건전지(＋ 위 물 · － 아래 물) + 펌프에서 온 번쩍이는 붉은 전선 / 문으로 가는 파란 전선': f'막전위(막을 가로지르는 전압 = 반대 전하의 격리 · 세포 안이 음 · −50 ~ −200 mV · 건전지처럼 에너지원) · 전기발생성 펌프(붉은 전선 — 3 내보내고 2 들여 순 ＋ 를 밖으로) · 저장된 에너지를 공동수송이 씀(파란 전선) 전용 {T} — L53c s7 ~ s10. ⚠ 다른 판에서 건전지를 그리지 말 것.',
 '＋ 표가 붙은 흰 소금 자루 ↓ / － 표가 붙은 흰 염소 ↑': f'막전위가 주는 방향 — 양이온은 (음인) 안으로 · 음이온은 밖으로 전용 {T} — L53c s9. 염소(뿔 · 턱수염의 흰 염소) = Cl⁻(염소 이온 — L17d#5 · L17e#1 톱니 기계의 염소와 같은 소리 고리 · 이 과에서 처음 동물로 그림). 처음 바탕의 염소는 「개미」로 읽혀 Gemini 구역 편집(E1)으로 다시 그렸다. ⚠ 다른 판에 염소 · 양을 다른 뜻으로 그리지 말 것.',
 '회전문에 함께 탄 두 손님(같은 칸 · ↓↓) / 혼자 탄 손님(↓) / 세로 문짝 양쪽 칸에 따로 탄 두 손님(↓ ↑)': f'symport(공수송) / uniport(단일수송) / antiport(역수송) 전용 {T} — L53c s10 ~ s12. 회전문 = 【구슬 기둥이 품은 회전문】(운반단백질). 첫 문 흰 소금 자루 + 포도 = Na⁺-포도당 공동수송(SGLT — 건전지의 파란 전선이 닿음 = 저장된 이온 기울기로 돈다 · 동전 투입구 없음 = 2차 능동) · 둘째 문 레몬 + 갈색 자루 + 꼭대기 해바라기 = H⁺-설탕 공동수송(식물) · 셋째 문 포도 혼자 = GLUT · 넷째 문 소금 자루 ↓ 자갈 ↑ = Na⁺/Ca²⁺ 교환체(심근). ⚠ 손님 · 문짝 · 화살은 PIL — 함께 타는 둘은 기운 문짝의 같은 칸에 · 맞바꾸는 둘은 세로 문짝 양쪽에.',
 '빨간 빨대가 꽂힌 유리컵 속 작은 흰 소금 자루와 포도': f'경구수액(NaCl + 포도당을 함께 — Na⁺-포도당 공동수송으로 흡수 · 물이 따라 듦) 전용 {T} — L53c s11 첫 회전문 위.',
 '금색 자물쇠가 채워진 작은 펌프 → 쌓인 흰 소금 자루 → 쌓인 회색 자갈 → 나무집 옆구리의 알통 팔이 자갈을 움켜쥠': f'강심배당체(우아바인 · 디곡신)의 길 — Na⁺/K⁺ 펌프 억제 → 세포 내 Na⁺ ↑ → Na⁺/Ca²⁺ 교환 ↓ → 세포 내 Ca²⁺ ↑ → 심근 수축력 ↑ 전용 {T} — L53c s13. 금색 자물쇠 = 약(【금색 자물쇠】 · L23a#2 의 그 자물쇠) · 자갈 = Ca²⁺ · 나무집(노란 반달 문) = 심장 집(L46 · 【종아리의 나무집 문신】). 반달 문은 PIL — 바탕의 네모 문을 바꿨다.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('동전 투입구 크랭크 펌프', f'★ {T} L53c 의 주인공 — 띠를 꿰뚫는 큰 놋쇠 기계(둥근 창의 유리 문짝 · 자루 셋 ↑ · 칼 둘 ↓ · 붉은 도장 · 밑면 투입구의 동전) + 맨 오른쪽의 작은 상자(크랭크에 금색 자물쇠 = 우아바인 · 디곡신).')
add('동전', f'★ {T} L53c s3 큰 펌프 기계 밑면 투입구로 ↑ 오르는 금 동전 = 능동수송의 직접 에너지원 ATP(세포 안에서 들어간다) · 회전문(공동수송)에는 투입구가 없다.')
add('붉은 민 도장', f'★ {T} L53c s3 · s5 · s6 펌프 왼쪽 옆구리에 나무 손잡이 도장이 찍은 붉은 자국 = 운반단백질의 인산화(ATP 가 인산기를 넘김) · 오른쪽 아래에서 들뜨고 기계 밑으로 떨어지는 붉은 조각 = 인산기 탈리(지우개 없이 「떨어짐」으로 그렸다 — 효소가 지우는 것이 아니라 제 걸음에서 떨어지므로).')
add('칼', f'★ {T} L53c — 펌프 창 오른쪽 칸의 칼 둘 ↓(K⁺ 2 안으로) · 아래 물에 빽빽한 칼 무리(세포 안 K⁺ 높음) · 위 물의 칼 둘(타려고 다가옴).')
add('근위세뇨관 짐꾼의 흰 소금 자루', f'★ {T} L53c — 펌프 창 왼쪽 칸의 자루 셋 ↑(Na⁺ 3 밖으로) · 위 물에 빽빽한 자루 무리 · 펌프 밑의 셋 · ＋ 표 자루(양이온) · 회전문의 짝 손님(포도와 함께 = symport · 자갈과 엇갈려 = antiport) · 자물쇠 펌프 밑에 쌓인 다섯(세포 내 Na⁺ 축적). 자루 꼴은 L53b 의 자루를 스프라이트로 옮겼다(Gemini 의 「흰 덩어리」 26개를 PIL 로 갈음).')
add('자갈', f'★ {T} L53c s12 · s13 넷째 회전문에서 소금 자루와 엇갈려 ↑ 나가는 자갈(Na⁺/Ca²⁺ 교환체) · 문 아래에 쌓인 자갈 여섯(세포 내 Ca²⁺ ↑) · 나무집의 알통 팔이 움켜쥔 자갈(Ca²⁺ → 심근 수축력 ↑).')
add('금색 자물쇠', f'★ {T} L53c s13 작은 펌프의 크랭크에 채워진 금색 자물쇠 = 우아바인 · 디곡신(강심배당체 — Na⁺/K⁺ 펌프 억제). L23a#2 와 같은 자물쇠.')
add('동글동글한 포도', f'★ {T} L53c — 첫 회전문에 흰 소금 자루와 함께 탄 포도(Na⁺-포도당 공동수송 · 아래 물에 포도가 여럿 = 거슬러 들임) · 셋째 회전문에 혼자 탄 포도(uniport · GLUT) · 경구수액 컵 속의 포도.')
add('구슬 기둥이 품은 회전문(양옆 놋쇠 굽은 벽 두 짝 사이에서 도는 유리 문짝)', f'★ {T} L53c 의 회전문 넷 — 손님 수와 화살이 종류다(함께 ↓↓ = symport · 혼자 ↓ = uniport · 엇갈려 ↓↑ = antiport). 큰 펌프 기계의 둥근 창도 같은 유리 문짝(운반단백질)이다.')
add('손을 맞잡은 포도와 흰 소금 자루(둘 다 얼굴 · 팔다리)', f'★ {T} L53c s10 · s11 그 둘이 첫 회전문의 같은 칸에 함께 탄다(얼굴 · 팔다리 없이 물건 꼴로).')
add('종아리의 나무집 문신', f'★ {T} L53c s13 오른쪽 아래의 작은 나무집(붉은 지붕 · 노란 반달 문) = 심장(심근) — 옆구리에서 솟은 알통 팔이 자갈을 움켜쥠 = 수축력 ↑.')
add('빈 주먹으로 알통을 세운 팔 / 국자를 쥔 팔', f'★ {T} L53c s13 나무집 옆구리에서 솟아 회색 자갈을 움켜쥔 알통 팔 = Ca²⁺ 로 세진 심근 수축(연장이 아니라 자갈 — 근육 팔 그대로).')
add('H⁺ — 퍼 던지는 · 뿌리는 맑은 물 / 쿠션 속 붉은 구슬', f'★ {T} 버터 부교(L53c)에서는 H⁺ 를 레몬으로 그린다(셀 수 있는 손님이어야 해서 — 레몬 = 산 · 【철봉을 오른쪽으로 미는 넷】 · 【레몬 뜬 초록 물 구덩이】와 같은 고리): 해바라기 회전문의 레몬 + 갈색 자루 = H⁺-설탕 공동수송.')
add('사람이 멘 자루 개수', f'★ {T} L53c 의 갈색 자루(물에 뜨고 회전문에 탐 · 사람이 메지 않음) = 설탕(자루 갈래 ③ — L22c 체관의 갈색 자루와 같은 뜻).')
add('바닷속을 가로지른 노란 버터 띠 + 머리만 물에 내놓은 두 줄 부표 사람', f'★ {T} L53c 는 같은 띠의 펌프 구간 — 왼쪽 큰 놋쇠 펌프(능동수송) → 가운데 건전지(막전위) → 오른쪽 회전문 넷(공동수송 · 단일수송 · 역수송) → 자물쇠 펌프(약). 세 장(a 구조 · b 저절로 드는 문 · c 동전 펌프)이 한 띠.')
open(P, 'w', encoding='utf-8').write(json.dumps(d, ensure_ascii=False, indent=1))
print('예약', len(R))
